<script setup>
import {onMounted,ref,computed} from 'vue'
import PageHeader from '../components/PageHeader.vue'
import {api} from '../lib/api.js'
const events=ref([]),nodes=ref([]),nodeId=ref(''),action=ref(''),port=ref(''),error=ref(''),message=ref(''),loading=ref(false),sessions=ref([]),duration=ref(24)
const totals=computed(()=>({allowed:events.value.filter(e=>e.action==='allow').length,blocked:events.value.filter(e=>e.action==='block').length}))
async function load(){loading.value=true;try{const query=new URLSearchParams({...(nodeId.value?{nodeId:nodeId.value}:{}),...(action.value?{action:action.value}:{}),...(port.value?{port:port.value}:{})});[events.value,sessions.value]=await Promise.all([api(`/logs/search?${query}`),api('/learning-sessions')]);error.value=''}catch(e){error.value=e.message}finally{loading.value=false}}
async function startLearning(){if(!nodeId.value)return;try{await api('/learning-sessions',{method:'POST',body:{nodeId:nodeId.value,durationHours:Number(duration.value)}});await load()}catch(e){error.value=e.message}}
async function finalize(session){try{const result=await api(`/learning-sessions/${session.id}/finalize`,{method:'POST',body:{}});message.value=result.status==='empty'?'No supported traffic was observed during this session':`Proposal generated with ${result.ruleCount} rules. Review it in Policy Studio before approval.`;await load()}catch(e){error.value=e.message}}
async function approve(session){try{const result=await api(`/learning-sessions/${session.id}/approve`,{method:'POST',body:{}});message.value=result.status==='enforced'?'Learned policy applied':result.status==='applying'?'Policy queued for agent application':'Policy apply failed; review the run before retrying';await load()}catch(e){error.value=e.message}}
async function pull(){if(!nodeId.value)return;try{await api('/logs/pull',{method:'POST',body:{nodeId:nodeId.value}});await load()}catch(e){error.value=e.message}}
onMounted(async()=>{nodes.value=await api('/nodes');await load()})
</script>
<template><div class="view"><PageHeader eyebrow="OBSERVABILITY / EVENTS" title="Firewall events" description="Search collected traffic and train a policy from observed flows"><button class="button secondary" :disabled="!nodeId" @click="pull"><i class="mdi mdi-download-network-outline"></i> Pull from node</button><button class="button primary" @click="load"><i class="mdi mdi-refresh"></i> Refresh</button></PageHeader><div v-if="error" class="error-msg">{{error}}</div><div v-if="message" class="success-msg">{{message}}</div><div class="metric-grid compact"><div class="metric glass"><div class="metric-top"><span>EVENTS IN VIEW</span><i class="mdi mdi-text-box-search-outline"></i></div><strong>{{events.length}}</strong></div><div class="metric glass"><div class="metric-top"><span>ALLOWED</span><i class="mdi mdi-check"></i></div><strong>{{totals.allowed}}</strong></div><div class="metric glass"><div class="metric-top"><span>BLOCKED</span><i class="mdi mdi-cancel"></i></div><strong>{{totals.blocked}}</strong></div><div class="metric glass"><div class="metric-top"><span>LEARNING SESSIONS</span><i class="mdi mdi-brain"></i></div><strong>{{sessions.length}}</strong></div></div><section class="panel glass"><div class="panel-title"><div><span class="eyebrow">EVENT SEARCH</span><h2>Traffic log</h2></div><div class="table-tools"><select v-model="nodeId" @change="load"><option value="">All nodes</option><option v-for="node in nodes" :key="node.id" :value="node.id">{{node.hostname}}</option></select><select v-model="action" @change="load"><option value="">All actions</option><option value="allow">Allow</option><option value="block">Block</option></select><input v-model="port" type="number" min="1" max="65535" placeholder="Port" @keyup.enter="load"><button class="icon-button" @click="load" title="Search"><i class="mdi mdi-magnify"></i></button></div></div><div class="table-wrap"><table><thead><tr><th>TIME</th><th>NODE</th><th>EVENT</th><th>ACTION</th><th>SOURCE</th><th>DESTINATION</th><th>PORT</th><th>PROGRAM</th></tr></thead><tbody><tr v-for="event in events" :key="event.id"><td>{{new Date(event.received_at).toLocaleString()}}</td><td class="mono">{{nodes.find(n=>n.id===event.node_id)?.hostname||event.node_id?.slice(0,8)}}</td><td>{{event.event_id}}</td><td><span class="status" :class="event.action">{{event.action}}</span></td><td class="mono">{{event.src_ip||'—'}}</td><td class="mono">{{event.dst_ip||'—'}}</td><td class="mono">{{event.dst_port||'—'}}</td><td class="mono">{{event.program||'—'}}</td></tr><tr v-if="!events.length"><td colspan="8" class="empty-table">No events found. Pull the Windows Security log or adjust filters.</td></tr></tbody></table></div></section><section class="panel glass"><div class="panel-title"><div><span class="eyebrow">POLICY DISCOVERY</span><h2>Learning sessions</h2></div><div class="table-tools"><input v-model.number="duration" type="number" min="1" max="720" aria-label="Duration in hours" style="width:90px"><span class="hint">hours</span><button class="button small secondary" :disabled="!nodeId" @click="startLearning">Start learning</button></div></div><div v-for="session in sessions" :key="session.id" class="history-row"><div><strong>{{nodes.find(n=>n.id===session.node_id)?.hostname||session.node_id}}</strong><small>{{session.status}} · ends {{new Date(session.ends_at).toLocaleString()}}</small></div><router-link v-if="session.generated_policy_id" class="button small secondary" :to="{path:'/policies',query:{policyId:session.generated_policy_id}}">Review policy</router-link><button v-if="session.status==='active'" class="button small secondary" @click="finalize(session)">Generate proposal</button><button v-if="['review','apply-failed'].includes(session.status)" class="button small primary" @click="approve(session)">Approve and apply</button></div><div v-if="!sessions.length" class="empty-side">No learning sessions yet.</div></section></div></template>
